const mails = await api.get("/mails", { label: "complaint" });
const items = mails.items || [];
const results = [];
for (const m of items) {
  if (m.customer_id) {
    const c = await api.get(`/customers/${m.customer_id}`);
    results.push({ mail_id: m.id, subject: m.subject, customer_id: m.customer_id, name: c.name, tier: c.tier });
  } else {
    results.push({ mail_id: m.id, subject: m.subject, customer_id: null, from_email: m.from_email, note: "고객 ID 없음" });
  }
}
return { count: mails.count, results };

